INSERT INTO `v1_d86695f6f4feffa653b12e35378875f932ed88af998d9c960d09ff4abaef055c` VALUES ("ミッションねえ……\nちょうどいいや\nどこまで片付けられるか\n賭けをしようじゃないか", 100, 2, "2030/01/01 14:59:59", 130011, -416.5, 3001100, 3001, 0, 1, 2.1, "ヤマト", "2024/10/31 12:00:00");
INSERT INTO `v1_d86695f6f4feffa653b12e35378875f932ed88af998d9c960d09ff4abaef055c` VALUES ("他人から言われた任務を\n言われるままにやるなんざ\n性に合わないんだがね……\nま、報酬は貰っとこうか", 101, 2, "2030/01/01 14:59:59", 130011, -416.5, 3001101, 3001, 0, 4, 5.68, "ヤマト", "2024/10/31 12:00:00");
INSERT INTO `v1_d86695f6f4feffa653b12e35378875f932ed88af998d9c960d09ff4abaef055c` VALUES ("なんだい？　やれンなら\nとっとと済ませちまいな。\nフブキが早くやることやれ\nってボヤいてたよ。", 102, 1, "2030/01/01 14:59:59", 130011, -416.5, 3001102, 3001, 0, 1, 0, "ヤマト", "2024/10/31 12:00:00");
INSERT INTO `v1_d86695f6f4feffa653b12e35378875f932ed88af998d9c960d09ff4abaef055c` VALUES ("え～？　ぼくに頼みごと～？\nどうしちゃおっかな～\nちゃんとお願いできたら\n考えてあげよっかな～？", 100, 1, "2030/01/01 14:59:59", 130211, -416.5, 3002100, 3002, 0, 1, 0, "フブキ", "2024/10/31 12:00:00");
INSERT INTO `v1_d86695f6f4feffa653b12e35378875f932ed88af998d9c960d09ff4abaef055c` VALUES ("ほらほらぁ、これが\n欲しいんでしょ～？\nほんと、しょうがないよね～\nザコおに～いさん♡", 101, 1, "2030/01/01 14:59:59", 130211, -416.5, 3002101, 3002, 0, 1, 0, "フブキ", "2024/10/31 12:00:00");
INSERT INTO `v1_d86695f6f4feffa653b12e35378875f932ed88af998d9c960d09ff4abaef055c` VALUES ("へえ～、欲しいんだ～？\nぼくのた・い・せ・つ・な・モ・ノ\nあははっ！　なに考えてんの？\nもうへんふしじゃ～んｗ", 102, 2, "2030/01/01 14:59:59", 130211, -416.5, 3002102, 3002, 0, 5, 8.53, "フブキ", "2024/10/31 12:00:00");
INSERT INTO `v1_d86695f6f4feffa653b12e35378875f932ed88af998d9c960d09ff4abaef055c` VALUES ("なになに～？　もしかしてまた\nおねだりするつもりなんだ？\nとか言って、ほんとはぼくに\n会いたいだけだったりして～？", 103, 1, "2030/01/01 14:59:59", 130211, -416.5, 3002103, 3002, 0, 7, 5.67, "フブキ", "2024/10/31 12:00:00");
INSERT INTO `v1_d86695f6f4feffa653b12e35378875f932ed88af998d9c960d09ff4abaef055c` VALUES ("ザコお兄さんってぇ\n頼み方もワンパなのぉ～？\nもっと必死にならないと\nぼくの心は動かせないよ～？", 104, 1, "2030/01/01 14:59:59", 130211, -416.5, 3002104, 3002, 0, 1, 0, "フブキ", "2024/10/31 12:00:00");
INSERT INTO `v1_d86695f6f4feffa653b12e35378875f932ed88af998d9c960d09ff4abaef055c` VALUES ("あのさーザコお兄さん、\nな～んか調子乗ってない？\nぼくのこと、なんでもくれる\nチョロいやつとか思ってたりー？", 300, 3, "2030/01/01 14:59:59", 130211, -416.5, 3002300, 3004, 0, 3, 0, "フブキ", "2024/10/31 12:00:00");
INSERT INTO `v1_d86695f6f4feffa653b12e35378875f932ed88af998d9c960d09ff4abaef055c` VALUES ("ざんね～ん♪\nうざいお兄さんには、もうな～んにもあげませ～ん♡\nほんとなっさけなーい♪\nばいば～い♡", 301, 7, "2030/01/01 14:59:59", 130211, -416.5, 3002400, 3005, 0, 7, 0, "フブキ", "2024/10/31 12:00:00");
INSERT INTO `v1_d86695f6f4feffa653b12e35378875f932ed88af998d9c960d09ff4abaef055c` VALUES ("きゃはは、ほんと必死～♡\nは～、面白かった。\n笑えたからいいよ～\nそれ、恵んだげる～♪", 200, 1, "2030/01/01 14:59:59", 130211, -416.5, 3003200, 3003, 0, 2, 4.4, "フブキ", "2024/10/31 12:00:00");
INSERT INTO `v1_d86695f6f4feffa653b12e35378875f932ed88af998d9c960d09ff4abaef055c` VALUES ("は～、しょうがないな～♡\nザコお兄さんってば\nほんとよわよわで\n情けないよね～ｗ", 201, 7, "2030/01/01 14:59:59", 130211, -416.5, 3003201, 3003, 0, 7, 0, "フブキ", "2024/10/31 12:00:00");
INSERT INTO `v1_d86695f6f4feffa653b12e35378875f932ed88af998d9c960d09ff4abaef055c` VALUES ("お兄さんってば、ぼくがいないと\nほんとザッコザコだよね～\nもっと感謝しろし～♪", 202, 2, "2030/01/01 14:59:59", 130211, -416.5, 3003202, 3003, 0, 1, 5.6, "フブキ", "2024/10/31 12:00:00");
